export function fmtBn(n: number): string {
  if (n >= 1000) return `$${(n / 1000).toFixed(2).replace(/\.?0+$/, "")}T`;
  return `$${n.toLocaleString()}B`;
}

export function fmtTn(n: number): string {
  return `$${n.toFixed(1)}T`;
}

