  return Number.isInteger(rounded)
    ? `$${rounded.toLocaleString()}B`
    : `$${rounded.toLocaleString(undefined, { maximumFractionDigits: 1 })}B`;
}

export function fmtDelta(n: number): string {
  const sign = n > 0 ? "+" : "";
